def b64(raw: bytes) -> str:
    return base64.b64encode(raw).decode()


def sign(vault: dict, signing_key: SigningKey, user_id: str = USER_ID) -> dict:
    signature = signing_key.sign(proof_payload(vault, user_id).encode("utf-8")).signature
    vault["proof"] = {
        "signature": b64(signature),
        "timestamp": 1792451124,
        "nonce": b64(secrets.token_bytes(16)),
    }
    return vault


def synthetic_vault(
    signing_key: SigningKey,
    *,
    version: int,
    password: bool = True,
    recovery: bool = True,
    confirmed: bool = False,
    user_id: str = USER_ID,
) -> dict:
    envelopes = []
    if password:
        envelopes.append(
            {
                "id": "env_password",
                "type": "password",
                "kdf": "argon2id",
                "params": {"m": 65536, "t": 3, "p": 4},
                "salt": b64(secrets.token_bytes(32)),
                "nonce": b64(secrets.token_bytes(12)),
                "ciphertext": b64(secrets.token_bytes(48)),
                "aad_version": 1,
            }
        )
    if recovery:
        envelopes.append(
            {
                "id": "env_recovery",
                "type": "recovery",
                "kdf": "hkdf-sha256",
                "salt": b64(secrets.token_bytes(32)),
                "nonce": b64(secrets.token_bytes(12)),
                "ciphertext": b64(secrets.token_bytes(48)),
                "aad_version": 1,
            }
        )
    vault = {
        "version": 1,
        "vault_version": version,
        "vault_pubkey": b64(bytes(signing_key.verify_key)),
        "private_key": {
            "nonce": b64(secrets.token_bytes(12)),
            "ciphertext": b64(secrets.token_bytes(48)),
            "aad_version": 1,
        },
        "bridge": {
            "kdf": "hkdf-sha256",
            "salt": b64(secrets.token_bytes(32)),
            "nonce": b64(secrets.token_bytes(12)),
            "ciphertext": b64(secrets.token_bytes(48)),
            "aad_version": 1,
        },
        "envelopes": envelopes,
        "recovery_confirmed": confirmed,
    }
    return sign(vault, signing_key, user_id)


class GoFixtureTests(SimpleTestCase):
    def test_go_fixture_verifies(self):
        validate_vault(GO_FIXTURE, user_id=USER_ID)

    def test_go_fixture_tamper_rejected(self):
        tampered = copy.deepcopy(GO_FIXTURE)
        tampered["envelopes"][0]["ciphertext"] = b64(secrets.token_bytes(48))
        with self.assertRaises(BodyValidationError):
            validate_vault(tampered, user_id=USER_ID)

    def test_go_fixture_wrong_user_rejected(self):
        with self.assertRaises(BodyValidationError):
            validate_vault(GO_FIXTURE, user_id="22222222-2222-2222-2222-222222222222")


class VaultPolicyTests(SimpleTestCase):
    def setUp(self):
        self.key = SigningKey.generate()

    def test_valid_password_rewrap(self):
        current = synthetic_vault(self.key, version=1, recovery=True, confirmed=True)
        nxt = synthetic_vault(self.key, version=2, recovery=True, confirmed=True)
        validate_vault_update(current, nxt, expected_version=1, user_id=USER_ID)

    def test_removing_last_recovery_after_confirmation_rejected(self):
        current = synthetic_vault(self.key, version=1, recovery=True, confirmed=True)
        nxt = synthetic_vault(self.key, version=2, recovery=False, confirmed=False)
        with self.assertRaises(BodyValidationError):
            validate_vault_update(current, nxt, expected_version=1, user_id=USER_ID)

    def test_removing_password_before_confirmation_rejected(self):
        current = synthetic_vault(self.key, version=1, recovery=True, confirmed=False)
        nxt = synthetic_vault(self.key, version=2, password=False, recovery=True, confirmed=False)
        with self.assertRaises(BodyValidationError):
            validate_vault_update(current, nxt, expected_version=1, user_id=USER_ID)

    def test_removing_recovery_before_confirmation_allowed(self):
        current = synthetic_vault(self.key, version=1, recovery=True, confirmed=False)
        nxt = synthetic_vault(self.key, version=2, recovery=False, confirmed=False)
        validate_vault_update(current, nxt, expected_version=1, user_id=USER_ID)

    def test_vault_pubkey_is_immutable(self):
        other = SigningKey.generate()
        current = synthetic_vault(self.key, version=1, recovery=True, confirmed=False)
        nxt = synthetic_vault(other, version=2, recovery=True, confirmed=False)
        with self.assertRaises(BodyValidationError):
            validate_vault_update(current, nxt, expected_version=1, user_id=USER_ID)

    def test_next_version_must_be_expected_plus_one(self):
        current = synthetic_vault(self.key, version=1, recovery=True, confirmed=False)
        nxt = synthetic_vault(self.key, version=3, recovery=True, confirmed=False)
        with self.assertRaises(BodyValidationError):
            validate_vault_update(current, nxt, expected_version=1, user_id=USER_ID)

    def test_confirmed_without_factor_rejected(self):
        vault = synthetic_vault(self.key, version=1, password=True, recovery=False, confirmed=True)
        with self.assertRaises(BodyValidationError):
            validate_vault(vault, user_id=USER_ID)

    def test_weak_kdf_rejected(self):
        vault = synthetic_vault(self.key, version=1, recovery=True, confirmed=False)
        vault["envelopes"][0]["params"] = {"m": 1024, "t": 3, "p": 4}
        sign(vault, self.key)
        with self.assertRaises(BodyValidationError):
            validate_vault(vault, user_id=USER_ID)

    def test_duplicate_envelope_id_rejected(self):
        vault = synthetic_vault(self.key, version=1, recovery=True, confirmed=False)
        vault["envelopes"][1]["id"] = vault["envelopes"][0]["id"]
        sign(vault, self.key)
        with self.assertRaises(BodyValidationError):
            validate_vault(vault, user_id=USER_ID)


class VaultEndpointTests(TestCase):
    def setUp(self):
        self.user = User.objects.create_user(
            email="vault@example.com",
            password="OldPassword123!",
            first_name="Vault",
            last_name="Tester",
        )
        self.key = SigningKey.generate()
        self.user_id = str(self.user.id)
        self.vault = synthetic_vault(
            self.key, version=1, recovery=True, confirmed=True, user_id=self.user_id
        )
        self.user.vault = self.vault
        self.user.vault_version = 1
        self.user.save(update_fields=["vault", "vault_version"])
        self.headers = {
            "HTTP_AUTHORIZATION": f"Bearer {RefreshToken.for_user(self.user).access_token}"
        }

    def next_vault(self, version=2, *, user_id=None, confirmed=True):
        return synthetic_vault(
            self.key,
            version=version,
            recovery=True,
            confirmed=confirmed,
            user_id=user_id or self.user_id,
        )

    def test_get_returns_vault(self):
        res = self.client.get("/api/auth/vault/", **self.headers)
        self.assertEqual(res.status_code, 200)
        data = res.json()["data"]
        self.assertEqual(data["vault_version"], 1)
        self.assertEqual(data["vault"]["vault_pubkey"], self.vault["vault_pubkey"])

    def test_put_updates_and_cas_rejects_stale_version(self):
        nxt = self.next_vault()
        res = self.client.put(
            "/api/auth/vault/",
            data=json.dumps({"expected_version": 1, "vault": nxt}),
            content_type="application/json",
            **self.headers,
        )
        self.assertEqual(res.status_code, 200)
        self.assertEqual(res.json()["data"]["vault_version"], 2)

        stale = self.client.put(
            "/api/auth/vault/",
            data=json.dumps({"expected_version": 1, "vault": self.next_vault(version=2)}),
            content_type="application/json",
            **self.headers,
        )
        self.assertEqual(stale.status_code, 409)

    def test_put_rejects_proof_for_another_user(self):
        nxt = self.next_vault(user_id="22222222-2222-2222-2222-222222222222")
        res = self.client.put(
            "/api/auth/vault/",
            data=json.dumps({"expected_version": 1, "vault": nxt}),
            content_type="application/json",
            **self.headers,
        )
        self.assertEqual(res.status_code, 422)

    def test_change_password_updates_vault(self):
        nxt = self.next_vault()
        res = self.client.patch(
            "/api/auth/change-password/",
            data=json.dumps(
                {
                    "current_password": "OldPassword123!",
                    "new_password": "NewPassword123!",
                    "key_salt": "new_salt",
                    "encrypted_private_key": "new_blob",
                    "vault": nxt,
                    "expected_version": 1,
                }
            ),
            content_type="application/json",
            **self.headers,
        )
        self.assertEqual(res.status_code, 200)
        self.user.refresh_from_db()
        self.assertTrue(self.user.check_password("NewPassword123!"))
        self.assertEqual(self.user.vault_version, 2)
        self.assertEqual(self.user.vault["vault_pubkey"], self.vault["vault_pubkey"])

    def test_change_password_stale_vault_does_not_change_password(self):
        res = self.client.patch(
            "/api/auth/change-password/",
            data=json.dumps(
                {
                    "current_password": "OldPassword123!",
                    "new_password": "NewPassword123!",
                    "key_salt": "new_salt",
                    "encrypted_private_key": "new_blob",
                    "vault": self.next_vault(),
                    "expected_version": 0,
                }
            ),
            content_type="application/json",
            **self.headers,
        )
        self.assertEqual(res.status_code, 409)
        self.user.refresh_from_db()
        self.assertTrue(self.user.check_password("OldPassword123!"))

    def test_change_password_without_vault_keeps_existing_vault(self):
        res = self.client.patch(
            "/api/auth/change-password/",
            data=json.dumps(
                {
                    "current_password": "OldPassword123!",
                    "new_password": "NewPassword123!",
                    "key_salt": "new_salt",
                    "encrypted_private_key": "new_blob",
                }
            ),
            content_type="application/json",
            **self.headers,
        )
        self.assertEqual(res.status_code, 200)
        self.user.refresh_from_db()
        self.assertEqual(self.user.vault_version, 1)
        self.assertEqual(self.user.vault["vault_pubkey"], self.vault["vault_pubkey"])


class VaultRecoveryEndpointTests(TestCase):
    """Password-less recovery: prove vault-key possession, then reset."""

    def setUp(self):
        self.user = User.objects.create_user(
            email="recover@example.com",
            password="ForgottenPassword123!",
            first_name="Recover",
            last_name="Tester",
        )
        self.key = SigningKey.generate()
        self.user_id = str(self.user.id)
        self.vault = synthetic_vault(
            self.key, version=1, recovery=True, confirmed=True, user_id=self.user_id
        )
        self.user.vault = self.vault
        self.user.vault_version = 1
        from apps.common.services.encryption import EncryptionService as encryption_service

        self.user.key_salt = encryption_service.encrypt("legacy_salt")
        self.user.encrypted_private_key = "legacy_blob"
        self.user.save(
            update_fields=["vault", "vault_version", "key_salt", "encrypted_private_key"]
        )

    def challenge(self, email="recover@example.com"):
        return self.client.post(
            "/api/auth/recover/challenge/",
            data=json.dumps({"email": email}),
            content_type="application/json",
        )

    def verify(self, challenge_data, *, key=None, email="recover@example.com"):
        signature = b64(
            (key or self.key).sign(challenge_data["challenge"].encode("utf-8")).signature
        )
        return self.client.post(
            "/api/auth/recover/verify/",
            data=json.dumps(
                {
                    "email": email,
                    "nonce": challenge_data["nonce"],
                    "signature": signature,
                }
            ),
            content_type="application/json",
        )

    def next_vault(self, version=2, *, key=None, user_id=None):
        return synthetic_vault(
            key or self.key,
            version=version,
            recovery=True,
            confirmed=True,
            user_id=user_id or self.user_id,
        )

    def test_challenge_and_verify_issue_recovery_session(self):
        res = self.challenge()
        self.assertEqual(res.status_code, 200)
        data = res.json()["data"]
        self.assertEqual(data["user_id"], self.user_id)
        self.assertEqual(data["vault_version"], 1)
        self.assertIn("as-vault-recover-v1", data["challenge"])

        # The unauthenticated challenge must not leak the password envelope.
        challenge_vault = data["vault"]
        self.assertEqual(
            [envelope["type"] for envelope in challenge_vault["envelopes"]],
            ["recovery"],
        )
        self.assertNotIn("proof", challenge_vault)
        self.assertNotIn("bridge", challenge_vault)

        verified = self.verify(data)
        self.assertEqual(verified.status_code, 200)
        payload = verified.json()["data"]
        self.assertTrue(payload["access"])
        self.assertEqual(payload["vault"]["vault_pubkey"], self.vault["vault_pubkey"])
        # The authenticated response carries the full vault, including the
        # password envelope needed to rewrap it.
        self.assertIn(
            "password", [envelope["type"] for envelope in payload["vault"]["envelopes"]]
        )

        from rest_framework_simplejwt.tokens import AccessToken

        self.assertTrue(AccessToken(payload["access"]).get("recovery"))

    def test_bad_signature_rejected_and_nonce_burned(self):
        data = self.challenge().json()["data"]
        wrong = SigningKey.generate()
        res = self.verify(data, key=wrong)
        self.assertEqual(res.status_code, 401)

        # The nonce was consumed by the failed attempt, so a retry fails too.
        self.assertEqual(self.verify(data).status_code, 401)

    def test_replayed_nonce_rejected(self):
        data = self.challenge().json()["data"]
        self.assertEqual(self.verify(data).status_code, 200)
        self.assertEqual(self.verify(data).status_code, 401)

    def test_unknown_email_gets_decoy_challenge(self):
        res = self.challenge("nobody@example.com")
        self.assertEqual(res.status_code, 200)
        data = res.json()["data"]
        self.assertEqual(data["user_id"], "")
        self.assertIsNone(data["vault"])

    def test_recovery_password_requires_recovery_session(self):
        normal = RefreshToken.for_user(self.user).access_token
        res = self.client.patch(
            "/api/auth/recover/password/",
            data=json.dumps(
                {
                    "new_password": "RecoveredPassword123!",
                    "key_salt": "new_salt",
                    "encrypted_private_key": "new_blob",
                    "vault": self.next_vault(),
                    "expected_version": 1,
                }
            ),
            content_type="application/json",
            HTTP_AUTHORIZATION=f"Bearer {normal}",
        )
        self.assertEqual(res.status_code, 401)

    def test_recovery_password_sets_new_password_and_vault(self):
        verified = self.verify(self.challenge().json()["data"])
        self.assertEqual(verified.status_code, 200)
        access = verified.json()["data"]["access"]

        res = self.client.patch(
            "/api/auth/recover/password/",
            data=json.dumps(
                {
                    "new_password": "RecoveredPassword123!",
                    "key_salt": "new_salt",
                    "encrypted_private_key": "new_blob",
                    "vault": self.next_vault(),
                    "expected_version": 1,
                }
            ),
            content_type="application/json",
            HTTP_AUTHORIZATION=f"Bearer {access}",
        )
        self.assertEqual(res.status_code, 200)
        self.user.refresh_from_db()
        self.assertTrue(self.user.check_password("RecoveredPassword123!"))
        self.assertFalse(self.user.check_password("ForgottenPassword123!"))
        self.assertEqual(self.user.vault_version, 2)
        self.assertEqual(self.user.encrypted_private_key, "new_blob")

    def test_recovery_password_clears_opaque_enrollment(self):
        from django.utils import timezone

        self.user.opaque_record = "record-for-the-forgotten-password"
        self.user.opaque_registered_at = timezone.now()
        self.user.save()

        verified = self.verify(self.challenge().json()["data"])
        self.assertEqual(verified.status_code, 200)
        access = verified.json()["data"]["access"]

        res = self.client.patch(
            "/api/auth/recover/password/",
            data=json.dumps(
                {
                    "new_password": "RecoveredPassword123!",
                    "key_salt": "new_salt",
                    "encrypted_private_key": "new_blob",
                    "vault": self.next_vault(),
                    "expected_version": 1,
                }
            ),
            content_type="application/json",
            HTTP_AUTHORIZATION=f"Bearer {access}",
        )
        self.assertEqual(res.status_code, 200)

        self.user.refresh_from_db()
        self.assertIsNone(self.user.opaque_record)
        self.assertIsNone(self.user.opaque_registered_at)

        # The new password authenticates: recovery must not leave the account
        # enrolled against the password the user no longer knows.
        login = self.client.post(
            "/api/auth/login/",
            data={"email": self.user.email, "password": "RecoveredPassword123!"},
            content_type="application/json",
        )
        self.assertEqual(login.status_code, 200)

    def test_recovery_password_rejects_stale_version(self):
        verified = self.verify(self.challenge().json()["data"])
        access = verified.json()["data"]["access"]
        res = self.client.patch(
            "/api/auth/recover/password/",
            data=json.dumps(
                {
                    "new_password": "RecoveredPassword123!",
                    "key_salt": "new_salt",
                    "encrypted_private_key": "new_blob",
                    "vault": self.next_vault(),
                    "expected_version": 0,
                }
            ),
            content_type="application/json",
            HTTP_AUTHORIZATION=f"Bearer {access}",
        )
        self.assertEqual(res.status_code, 409)

    def test_recovery_password_rejects_a_different_vault_key(self):
        verified = self.verify(self.challenge().json()["data"])
        access = verified.json()["data"]["access"]
        res = self.client.patch(
            "/api/auth/recover/password/",
            data=json.dumps(
                {
                    "new_password": "RecoveredPassword123!",
                    "key_salt": "new_salt",
                    "encrypted_private_key": "new_blob",
                    "vault": self.next_vault(key=SigningKey.generate()),
                    "expected_version": 1,
                }
            ),
            content_type="application/json",
            HTTP_AUTHORIZATION=f"Bearer {access}",
        )
        self.assertEqual(res.status_code, 422)
